-- Migration: Create wilayah table
-- Source: Kepmendagri No 300.2.2-2430 Tahun 2025 (via cahyadsn/wilayah)

DROP TABLE IF EXISTS wilayah;

CREATE TABLE wilayah (
    kode TEXT PRIMARY KEY,
    kode_bps TEXT NOT NULL,
    nama TEXT NOT NULL,
    level INTEGER NOT NULL,
    parent_kode TEXT,
    lat REAL,
    lng REAL,
    kodepos TEXT
);

CREATE INDEX idx_parent ON wilayah(parent_kode);
CREATE INDEX idx_level ON wilayah(level);
CREATE INDEX idx_nama ON wilayah(nama COLLATE NOCASE);
CREATE INDEX idx_kodepos ON wilayah(kodepos);
CREATE INDEX idx_kode_bps ON wilayah(kode_bps);
























































































































































































